import json

from shelf import books, report


def setup_function():
    books.clear()


def test_by_author_counts():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    books.add("Persuasion", "Jane Austen")
    assert report.by_author() == {"Frank Herbert": 1, "Jane Austen": 2}


def test_by_author_empty():
    assert report.by_author() == {}


def test_as_json():
    books.add("Dune", "Frank Herbert")
    data = json.loads(report.as_json())
    assert data == {"summary": "1 books", "by_author": {"Frank Herbert": 1}}
EOF
